package com.internalops.aftersales;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import static org.junit.jupiter.api.Assertions.assertTrue;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class AfterSalesQueryServiceTest{@Test void detailKeepsCamelCaseCollectionKeys(){JdbcTemplate jdbc=mock(JdbcTemplate.class);Map<String,Object> header=new LinkedHashMap<>();header.put("id",1L);header.put("after_sales_no","AS1");when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(header),List.of(Map.of("requested_quantity",2)),List.of(),List.of());Map<String,Object> result=new AfterSalesQueryService(jdbc).get(1);assertTrue(result.containsKey("returnLines"));assertTrue(result.containsKey("replacementLines"));assertTrue(result.containsKey("events"));}}
